127|const NUMBER_WORDS: Record<string, string> = {
128|  two: '2', three: '3', four: '4', five: '5', six: '6', seven: '7', eight: '8', nine: '9', ten: '10',
129|  eleven: '11', twelve: '12', thirteen: '13', fourteen: '14', fifteen: '15', sixteen: '16', seventeen: '17',
130|  eighteen: '18', nineteen: '19', twenty: '20', thirty: '30', forty: '40', fifty: '50', sixty: '60',
131|  seventy: '70', eighty: '80', ninety: '90', hundred: '100',
132|};
133|const NUMBER_WORD_RE = new RegExp(`\\b(${Object.keys(NUMBER_WORDS).join('|')})\\b`, 'g');
134|// "eighty-one" or "eighty one" is 81, one number, not 80 and 1. Spoken dictation
135|// and model prose both write compounds; the gate must read them as the clinician meant.
136|const TENS = 'twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety';
137|const ONES = 'one|two|three|four|five|six|seven|eight|nine';
138|const COMPOUND_RE = new RegExp(`\\b(${TENS})[ -](${ONES})\\b`, 'g');
139|const ONES_VALUE: Record<string, number> = { one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9 };
140|// "one hundred ten", "two hundred", "three hundred twenty-five", "a hundred and five":
141|// one number each. Found live Oct 28 (muse-spark-1.3 with CHART, case-032): the
142|// gate read "one hundred ten feet" as 1, 100, 10 and refuted a true sentence.
143|const TEENS = 'ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen';
144|const HUNDREDS_RE = new RegExp(
145|  `\\b(${ONES}|a)[ -]hundred(?:[ -](?:and[ -])?(?:(${TENS})(?:[ -](${ONES}))?|(${TEENS})|(${ONES})))?\\b`,
146|  'g',
147|);
148|function hundreds(_: string, h: string, tens?: string, tensOnes?: string, teen?: string, ones?: string): string {
149|  let n = (h === 'a' ? 1 : ONES_VALUE[h]!) * 100;
150|  if (tens) n += Number(NUMBER_WORDS[tens]) + (tensOnes ? ONES_VALUE[tensOnes]! : 0);
151|  else if (teen) n += Number(NUMBER_WORDS[teen]);
152|  else if (ones) n += ONES_VALUE[ones]!;
153|  return String(n);
154|}
