247|// The smallest set of other entries that, together, source every missing
248|// token: each token is matched to the first entry (in chart order) that holds
249|// it. Null when any token is in no entry at all.
250|function sourcedElsewhere(chart: GateEntry[], citedId: string, missing: string[]): string[] | null {
251|  const found: string[] = [];
252|  const tokensOf = new Map<string, Set<string>>();
253|  for (const token of missing) {
254|    let holder: string | null = null;
255|    for (const entry of chart) {
256|      if (entry.id === citedId) continue;
257|      let set = tokensOf.get(entry.id);
258|      if (!set) {
259|        set = new Set<string>();
260|        // An entry that cannot be read is skipped here, never thrown: the
261|        // cited entry's own check already decided this sentence's status.
262|        try {
263|          sourceTokens(entry.text, set);
264|          if (entry.date) sourceTokens(entry.date, set);
265|        } catch {
266|          set = new Set<string>();
267|        }
268|        tokensOf.set(entry.id, set);
269|      }
270|      if (set.has(token)) { holder = entry.id; break; }
271|    }
272|    if (holder === null) return null;
273|    if (!found.includes(holder)) found.push(holder);
274|  }
275|  return found;
