280|// Tokens every sentence of a case may carry: from the payer criteria, the
281|// denial, and the stated case facts. The cited entry's own tokens are added
282|// per sentence.
283|function sharedTokens(sources: GateSources): Set<string> {
284|  const shared = new Set<string>();
285|  for (const c of sources.criteria) sourceTokens(c.text, shared);
286|  for (const d of sources.denial) sourceTokens(d, shared);
287|  for (const x of sources.facts ?? []) sourceTokens(x, shared);
288|  return shared;
