102|export const CHART_TOOLS: ToolDefinition[] = [
103|  {
104|    name: 'list_entries',
105|    description: 'Lists every entry in the chart: id, date, kind, and opening words. The same index you were given.',
106|    inputSchema: { type: 'object', properties: {}, additionalProperties: false },
107|  },
108|  {
109|    name: 'read_entry',
110|    description: 'Returns the full text of one chart entry by id, e.g. note-012. Quote only from entries you have read with this tool.',
111|    // `why` (Oct 31): the Meta API returns only redacted thinking, so the model
112|    // states in one sentence why it is opening the entry; the trace records it
113|    // and the viewer shows it as the entry lights. The executor ignores it.
114|    inputSchema: { type: 'object', required: ['id', 'why'], properties: { id: { type: 'string', description: 'the entry id, like note-012' }, why: { type: 'string', description: 'one sentence: what you expect this entry to bear on and why you are opening it now' } }, additionalProperties: false },
115|  },
