133|export function buildAgenticRequest(c: SyntheticCase, effort: Effort, maxTokens: number, options: { tools?: ToolDefinition[]; extra?: (call: ToolCall) => Promise<ToolOutcome | null>; side?: Side } = {}): AgenticRequest {
134|  const side: Side = options.side ?? 'physician';
135|  const base = buildRequest(c, effort, maxTokens, side);
136|  const hasPolicyStatus = (options.tools ?? []).some(t => t.name === POLICY_STATUS_TOOL.name);
137|  const policyLine = hasPolicyStatus
138|    ? `\n\nA third tool, policy_status, is a live query against CHART, a pre-existing coverage index. The payer here is fictional, so call it once with authority "${DEFAULT_AUTHORITY}", the code on the denial, and the date of service, before you decide; report what it says about freshness only in your reasoning, never as a chart fact.`
139|    : '';
140|  return {
141|    ...base,
142|    system: [
143|      { text: side === 'payer' ? INSTRUCTIONS_PAYER_AGENTIC : INSTRUCTIONS_AGENTIC, cache: true },
144|      { text: `Chart index for patient ${c.patient.alias}, ${c.patient.age} year old ${c.patient.sex}. Synthetic record. ${c.chart.length} entries.\n\n${chartIndex(c)}${policyLine}` },
145|    ],
146|    tools: [...CHART_TOOLS, ...(options.tools ?? [])],
147|    execute: chartToolExecutor(c, options.extra),
148|    maxTurns: 24,
149|  };
150|}
