156|export function buildRequest(c: SyntheticCase, effort: Effort, maxTokens: number, side: Side = 'physician'): ProposeRequest {
157|  const criteria = c.criteria.map(k => `${k.id}: ${k.text}`).join('\n');
158|  const ask = side === 'payer' ? 'Decide whether the denial is supported by the record and, if so, draft the determination.' : 'Decide whether an appeal is warranted and, if so, draft it.';
159|  return {
160|    system: [
161|      { text: side === 'payer' ? INSTRUCTIONS_PAYER : INSTRUCTIONS, cache: true },
162|      { text: `Chart for patient ${c.patient.alias}, ${c.patient.age} year old ${c.patient.sex}. Synthetic record.\n\n${renderChart(c)}` },
163|    ],
164|    user: `Denial (CARC ${c.denial.carc}): ${c.denial.text}\n\nService: ${c.procedure.codeSystem} ${c.procedure.code}, ${c.procedure.description}.\n\nPayer criteria (${c.payer.name}, ${c.payer.planType}):\n${criteria}\n\n${ask}`,
165|    effort,
166|    maxTokens,
167|  };
