212|// One repair turn: the gate's reasons sent back verbatim, the revised draft,
213|// its gate record, and what the turn cost. Offered only on a blocked draft,
214|// never on a declined one.
215|export interface RepairRecord {
216|  turn: number; // 1-based
217|  reasons: string[]; // the gate's lines as sent: sentence index, status, reason, alsoCite entries; criteria without evidence
218|  sent: string; // the user turn, verbatim
219|  stopReason: string | null;
220|  latencyMs: number;
221|  usage: Usage;
222|  costUsd: number;
223|  toolCalls: number; // agentic: calls made in this turn; the events are in trace[] with repair = turn
