230|export interface RunOptions {
231|  effort: Effort;
232|  maxTokens: number;
233|  agentic?: boolean;
234|  tools?: ToolDefinition[]; // extra tools for the agentic path
235|  extra?: (call: ToolCall) => Promise<ToolOutcome | null>;
236|  side?: Side; // payer: the same gate pointed at the insurer's determination
237|  repair?: number; // repair turns to offer a blocked draft; default 0
238|  verbose?: boolean; // stream one line per tool call and the verdict to `log`
239|  log?: (line: string) => void; // default: stderr
