1|// The LITMUS gate, reimplemented during the event from the published papers
2|// (Litmus: The Admissible Set, doi 10.5281/zenodo.21227402, and its
3|// architecture companion, doi 10.5281/zenodo.21227855). Not copied from writ.
4|//
5|// What the papers fix:
6|//   - The check is deterministic and sits outside the model. A model grading
7|//     a model is the weak litmus the paper names as the one that fell away.
8|//   - It fails closed. Nothing ungrounded leaves; the worst case is deferral.
9|//   - Chart grounding is a referential warrant: it verifies that the draft
10|//     says what the record says, not that the care was right. Judgment stays
11|//     with the physician, who sees criterion, quote, and sentence together.
12|//   - Every claim, gate decision, and verdict is recorded (the provenance layer).
13|//
14|// How this gate checks support (the part the papers leave to the builder):
15|//   1. Resolve the citation to one chart entry. Unknown or malformed: unresolved.
16|//   2. The quote must appear verbatim in that entry's text (whitespace, case,
17|//      quote glyphs, and dash variants normalized: curly quotes to straight,
18|//      en, em, and figure dashes and the minus sign to the ASCII hyphen;
19|//      nothing else). Absent or trivial: refuted.
20|//   3. Every hard token in the sentence (numbers, dates, codes, and a side,
21|//      left or right) must appear in the cited entry, the payer criteria,
22|//      the denial, or the stated case facts. Anything else: refuted, token named.
23|//      The whole cited entry counts, not only the quoted span: the gate exists
24|//      to catch invented facts, not to grade quoting form, and the clinician who
25|//      wrote the entry did not write it to a payer's vocabulary.
26|//   4. A check that throws is an error, never a refutation and never a pass.
27|// There is no resemblance threshold and no keyword list. The evidence is the
28|// clinician's own words, which no payer vocabulary can require.
29|import { sha256Hex } from './hash.js';
30|import { CITATION_ID } from './citation.js';
31|import type { Appeal } from './schema.js';
32|
33|export const LITMUS_VERSION = 'build/src/litmus.ts v1.5 (2026-10-31): exact-quote referential gate from the LITMUS papers; compound number words read as one number; a sentence whose unsourced tokens all live in another chart entry is returned as needs-citation naming that entry, still blocked; a side (left or right) is a hard token wherever it names a side, not only before a fixed anatomy list; a side that a source carries only inside an idiom (right back to baseline) is not an admissible source for a side';
34|
35|export interface GateEntry {
36|  id: string;
37|  date?: string;
38|  kind?: string;
39|  text: string;
40|}
41|
42|export interface GateCriterion {
43|  id: string;
44|  text: string;
45|}
46|
47|export interface GateSources {
48|  chart: GateEntry[];
49|  criteria: GateCriterion[];
50|  denial: string[]; // the denial's text fields: numbers here are admissible
51|  facts?: string[]; // other admissible case facts, e.g. the patient's age line
52|}
53|
54|// needs-citation: every hard token the cited entry lacks is present in another
55|// entry of the same chart. The sentence may well be true, but the rule is one
56|// citation per sentence and every hard token in it, so the draft is still
57|// blocked; the record names the entry to add, so the physician is told what to
58|// fix rather than that the machine disagrees. A token found nowhere in the
59|// chart stays refuted: that is the invented-fact case the gate exists for.
60|export type SentenceStatus = 'verified' | 'unresolved' | 'refuted' | 'needs-citation' | 'error';
61|
62|// Only this module holds the symbol, so only this module can build a record
63|// whose status is 'verified'. Other code can read the status; it cannot mint it.
64|const VERIFIED: unique symbol = Symbol('litmus.verified');
65|
66|interface SentenceBase {
67|  index: number;
68|  text: string;
69|  citation: string;
70|  quote: string;
71|  reason: string; // a short code plus detail, e.g. 'unsourced-token: 16'
72|  missing?: string[]; // hard tokens with no admissible source
73|  alsoCite?: string[]; // needs-citation: chart entries that together source every missing token
74|}
75|export interface VerifiedSentence extends SentenceBase {
76|  status: 'verified';
77|  readonly [VERIFIED]: true;
78|}
79|export interface UnverifiedSentence extends SentenceBase {
80|  status: 'unresolved' | 'refuted' | 'needs-citation' | 'error';
81|}
82|export type SentenceRecord = VerifiedSentence | UnverifiedSentence;
83|
84|interface EvidenceBase {
85|  index: number;
86|  criterion: string;
87|  citation: string;
88|  quote: string;
89|  reason: string;
90|}
91|export interface VerifiedEvidence extends EvidenceBase {
92|  status: 'verified';
93|  readonly [VERIFIED]: true;
94|}
95|export interface UnverifiedEvidence extends EvidenceBase {
96|  status: 'unresolved' | 'refuted' | 'error';
97|}
98|export type EvidenceRecord = VerifiedEvidence | UnverifiedEvidence;
99|
100|export interface GateResult {
101|  litmus: string;
102|  verdict: 'pass' | 'blocked' | 'declined';
103|  reasons: string[]; // why a packet is blocked, one line each
104|  errored: boolean; // at least one check threw: distinguishable from refuted
105|  declinedReason?: string;
106|  sentences: SentenceRecord[];
107|  evidence: EvidenceRecord[];
108|  criteria: Record<string, 'verified' | 'unverified'>;
109|  counts: { sentences: number; verified: number; unresolved: number; refuted: number; needsCitation: number; error: number; evidence: number; evidenceVerified: number };
110|  inputHash: string; // sha256 of the sources and the draft, for the provenance record
111|}
112|
113|// --- text normalization -----------------------------------------------------
114|
115|function canon(s: string): string {
116|  return s
117|    .normalize('NFC')
118|    .replace(/[‘’‚‛′]/g, "'")
119|    .replace(/[“”„‟″]/g, '"')
120|    .replace(/[‐-―−]/g, '-')
121|    .replace(/ /g, ' ')
122|    .replace(/\s+/g, ' ')
123|    .trim()
124|    .toLowerCase();
125|}
126|
127|const NUMBER_WORDS: Record<string, string> = {
128|  two: '2', three: '3', four: '4', five: '5', six: '6', seven: '7', eight: '8', nine: '9', ten: '10',
129|  eleven: '11', twelve: '12', thirteen: '13', fourteen: '14', fifteen: '15', sixteen: '16', seventeen: '17',
130|  eighteen: '18', nineteen: '19', twenty: '20', thirty: '30', forty: '40', fifty: '50', sixty: '60',
131|  seventy: '70', eighty: '80', ninety: '90', hundred: '100',
132|};
133|const NUMBER_WORD_RE = new RegExp(`\\b(${Object.keys(NUMBER_WORDS).join('|')})\\b`, 'g');
134|// "eighty-one" or "eighty one" is 81, one number, not 80 and 1. Spoken dictation
135|// and model prose both write compounds; the gate must read them as the clinician meant.
136|const TENS = 'twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety';
137|const ONES = 'one|two|three|four|five|six|seven|eight|nine';
138|const COMPOUND_RE = new RegExp(`\\b(${TENS})[ -](${ONES})\\b`, 'g');
139|const ONES_VALUE: Record<string, number> = { one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9 };
140|// "one hundred ten", "two hundred", "three hundred twenty-five", "a hundred and five":
141|// one number each. Found live Oct 28 (muse-spark-1.3 with CHART, case-032): the
142|// gate read "one hundred ten feet" as 1, 100, 10 and refuted a true sentence.
143|const TEENS = 'ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen';
144|const HUNDREDS_RE = new RegExp(
145|  `\\b(${ONES}|a)[ -]hundred(?:[ -](?:and[ -])?(?:(${TENS})(?:[ -](${ONES}))?|(${TEENS})|(${ONES})))?\\b`,
146|  'g',
147|);
148|function hundreds(_: string, h: string, tens?: string, tensOnes?: string, teen?: string, ones?: string): string {
149|  let n = (h === 'a' ? 1 : ONES_VALUE[h]!) * 100;
150|  if (tens) n += Number(NUMBER_WORDS[tens]) + (tensOnes ? ONES_VALUE[tensOnes]! : 0);
151|  else if (teen) n += Number(NUMBER_WORDS[teen]);
152|  else if (ones) n += ONES_VALUE[ones]!;
153|  return String(n);
154|}
155|
156|function prepare(text: string): string {
157|  return canon(text)
158|    .replace(/\bnote-\d{3}\b/g, ' ')
159|    .replace(/\bcrit-\d+\b/g, ' ')
160|    .replace(HUNDREDS_RE, hundreds)
161|    .replace(COMPOUND_RE, (_, tens: string, ones: string) => String(Number(NUMBER_WORDS[tens]) + ONES_VALUE[ones]!))
162|    .replace(NUMBER_WORD_RE, w => NUMBER_WORDS[w]!);
163|}
164|
165|function stripZeros(n: string): string {
166|  return n.replace(/^0+(?=\d)/, '');
167|}
168|
169|// v1.4: a side is a hard token wherever it names a side. v1.3 recognized a side
170|// only before a fixed list of anatomical words, and the mutation harness
171|// (scripts/mutate.ts, Oct 28) found 48 swapped sides passing in contexts outside
172|// that list: "left ventricle", "left forefoot ulcer", "right great toe extensor",
173|// "left total knee arthroplasty". The uses of left and right that are not sides
174|// ("left the clinic", "right back to baseline") are masked before the check.
175|// v1.5: the same mask applies to the sources. Until Oct 31 only the sentence
176|// was masked, so an entry that carried "right back to baseline" made the bare
177|// word admissible for every sentence citing it, and an invented right-sided
178|// claim citing such an entry was verified (found in review on case-006
179|// note-017; the shunt-direction pair "left to right" / "right to left" leaked
180|// the same way). The idiom list is fixed and not exhaustive; it is applied
181|// identically on both sides of the check.
182|const SIDE_IDIOM = /\bright (?:back|away|now|after|before|here|there|then|to|at)\b|\bleft (?:the|a|an|against|behind|over|off|out|in|to|for|at|on|with|without|home|early|before|after|us|him|her|them|it|from)\b/g;
183|
184|// Hard tokens of a sentence: the facts that must have an admissible source.
185|function sentenceHardTokens(text: string): Set<string> {
186|  const t = prepare(text);
187|  const out = new Set<string>();
188|  for (const m of t.matchAll(/\b(\d{4})-(\d{2})-(\d{2})\b/g)) out.add(m[0]);
189|  for (const m of t.matchAll(/\b(\d{1,2})\/(\d{1,2})\/(\d{2,4})\b/g)) out.add(m[0]);
190|  for (const m of t.matchAll(/\d+(?:\.\d+)?/g)) out.add(stripZeros(m[0]));
191|  for (const m of t.matchAll(/\b[a-z]\d{2}(?:\.\d+)?\b/g)) out.add(m[0]);
192|  for (const m of t.replace(SIDE_IDIOM, ' ').matchAll(/\b(left|right)\b/g)) out.add(m[1]!);
193|  if (/\bbilateral(?:ly)?\b/.test(t)) out.add('bilateral');
194|  out.delete('');
195|  return out;
196|}
197|
198|// Admissible tokens of a source: everything a sentence may legitimately carry.
199|function sourceTokens(text: string, into: Set<string>): void {
200|  const t = prepare(text);
201|  for (const m of t.matchAll(/\b(\d{4})-(\d{2})-(\d{2})\b/g)) {
202|    into.add(m[0]);
203|    into.add(stripZeros(m[1]!));
204|    into.add(stripZeros(m[2]!));
205|    into.add(stripZeros(m[3]!));
206|  }
207|  for (const m of t.matchAll(/\b(\d{1,2})\/(\d{1,2})\/(\d{2,4})\b/g)) {
208|    into.add(m[0]);
209|    into.add(stripZeros(m[1]!));
210|    into.add(stripZeros(m[2]!));
211|    into.add(stripZeros(m[3]!));
212|  }
213|  for (const m of t.matchAll(/\d+(?:\.\d+)?/g)) into.add(stripZeros(m[0]));
214|  for (const m of t.matchAll(/\b[a-z]\d{2}(?:\.\d+)?\b/g)) into.add(m[0]);
215|  for (const m of t.replace(SIDE_IDIOM, ' ').matchAll(/\b(left|right)\b/g)) into.add(m[1]!);
216|  if (/\bbilateral(?:ly)?\b/.test(t)) into.add('bilateral');
217|}
218|
219|// --- the checks --------------------------------------------------------------
220|
221|type Check = { ok: true } | { ok: false; status: 'unresolved' | 'refuted'; reason: string; missing?: string[] };
222|
223|function resolve(chart: GateEntry[], citation: string): { ok: true; entry: GateEntry } | { ok: false; status: 'unresolved'; reason: string } {
224|  if (!CITATION_ID.test(citation)) return { ok: false, status: 'unresolved', reason: `citation-malformed: ${citation.slice(0, 40) || '(empty)'}` };
225|  const entry = chart.find(e => e.id === citation);
226|  if (!entry) return { ok: false, status: 'unresolved', reason: `citation-unknown: ${citation}` };
227|  return { ok: true, entry };
228|}
229|
230|function checkQuote(entry: GateEntry, quote: string): Check {
231|  const q = canon(quote);
232|  if (q.length === 0) return { ok: false, status: 'refuted', reason: 'quote-empty' };
233|  // Two words, or one substantive word of five or more letters ("Nonsmoker"). Never "the" or "PT".
234|  const words = q.split(' ').filter(w => /[a-z0-9]/.test(w));
235|  const substantive = words.length === 1 && /^[a-z]{5,}$/.test(words[0]!);
236|  if (words.length < 2 && !substantive) return { ok: false, status: 'refuted', reason: 'quote-too-short: a quote must be at least two words, or one substantive word' };
237|  if (!canon(entry.text).includes(q)) return { ok: false, status: 'refuted', reason: `quote-not-in-entry: the quote does not appear verbatim in ${entry.id}` };
238|  return { ok: true };
239|}
240|
241|function checkHardTokens(text: string, allowed: Set<string>): Check {
242|  const missing = [...sentenceHardTokens(text)].filter(t => !allowed.has(t));
243|  if (missing.length > 0) return { ok: false, status: 'refuted', reason: `unsourced-token: ${missing.join(', ')}`, missing };
244|  return { ok: true };
245|}
246|
247|// The smallest set of other entries that, together, source every missing
248|// token: each token is matched to the first entry (in chart order) that holds
249|// it. Null when any token is in no entry at all.
250|function sourcedElsewhere(chart: GateEntry[], citedId: string, missing: string[]): string[] | null {
251|  const found: string[] = [];
252|  const tokensOf = new Map<string, Set<string>>();
253|  for (const token of missing) {
254|    let holder: string | null = null;
255|    for (const entry of chart) {
256|      if (entry.id === citedId) continue;
257|      let set = tokensOf.get(entry.id);
258|      if (!set) {
259|        set = new Set<string>();
260|        // An entry that cannot be read is skipped here, never thrown: the
261|        // cited entry's own check already decided this sentence's status.
262|        try {
263|          sourceTokens(entry.text, set);
264|          if (entry.date) sourceTokens(entry.date, set);
265|        } catch {
266|          set = new Set<string>();
267|        }
268|        tokensOf.set(entry.id, set);
269|      }
270|      if (set.has(token)) { holder = entry.id; break; }
271|    }
272|    if (holder === null) return null;
273|    if (!found.includes(holder)) found.push(holder);
274|  }
275|  return found;
276|}
277|
278|// --- the gate ----------------------------------------------------------------
279|
280|// Tokens every sentence of a case may carry: from the payer criteria, the
281|// denial, and the stated case facts. The cited entry's own tokens are added
282|// per sentence.
283|function sharedTokens(sources: GateSources): Set<string> {
284|  const shared = new Set<string>();
285|  for (const c of sources.criteria) sourceTokens(c.text, shared);
286|  for (const d of sources.denial) sourceTokens(d, shared);
287|  for (const x of sources.facts ?? []) sourceTokens(x, shared);
288|  return shared;
289|}
290|
291|export interface SentenceInput { text: string; citation: string; quote: string }
292|
293|// One sentence through the gate. This is the function litmus() applies to each
294|// sentence of a draft; it is exported so the viewer can re-check a sentence a
295|// reader has edited, in the browser, with the same code and the same sources
296|// (viewer/src/gatecheck.ts). The optional shared set lets litmus() compute the
297|// case-level tokens once per draft.
298|export function checkSentence(sources: GateSources, s: SentenceInput, index = 0, shared: Set<string> = sharedTokens(sources)): SentenceRecord {
299|  const base: SentenceBase = { index, text: s.text, citation: s.citation, quote: s.quote, reason: '' };
300|  try {
301|    const r = resolve(sources.chart, s.citation);
302|    if (!r.ok) return { ...base, status: r.status, reason: r.reason };
303|    const q = checkQuote(r.entry, s.quote);
304|    if (!q.ok) return { ...base, status: q.status, reason: q.reason };
305|    const allowed = new Set(shared);
306|    sourceTokens(r.entry.text, allowed);
307|    if (r.entry.date) sourceTokens(r.entry.date, allowed);
308|    const h = checkHardTokens(s.text, allowed);
309|    if (!h.ok) {
310|      const elsewhere = h.missing ? sourcedElsewhere(sources.chart, r.entry.id, h.missing) : null;
311|      if (elsewhere) return { ...base, status: 'needs-citation', reason: `needs-citation: ${h.missing!.join(', ')} not in ${r.entry.id}; the chart has it in ${elsewhere.join(', ')}. If that entry is the source, cite it as well; if it is a count or figure the chart never states, rewrite the sentence`, missing: h.missing!, alsoCite: elsewhere };
312|      return { ...base, status: h.status, reason: h.reason, ...(h.missing ? { missing: h.missing } : {}) };
313|    }
314|    return { ...base, status: 'verified', reason: 'verified: quote found in the cited entry; every hard token sourced from the entry, the criteria, the denial, or the case facts', [VERIFIED]: true };
315|  } catch (error: unknown) {
316|    return { ...base, status: 'error', reason: `error: ${error instanceof Error ? error.message : String(error)}` };
317|  }
