320|export function litmus(sources: GateSources, appeal: Appeal): GateResult {
321|  const inputHash = sha256Hex(JSON.stringify({ chart: sources.chart, criteria: sources.criteria, denial: sources.denial, facts: sources.facts ?? [], appeal }));
322|
323|  const shared = sharedTokens(sources);
324|  const criterionIds = new Set(sources.criteria.map(c => c.id));
325|
326|  const sentences: SentenceRecord[] = appeal.sentences.map((s, index) => checkSentence(sources, s, index, shared));
327|
328|  const evidence: EvidenceRecord[] = appeal.evidence.map((e, index) => {
329|    const base: EvidenceBase = { index, criterion: e.criterion, citation: e.citation, quote: e.quote, reason: '' };
330|    try {
331|      if (!criterionIds.has(e.criterion)) return { ...base, status: 'unresolved', reason: `criterion-unknown: ${e.criterion.slice(0, 40) || '(empty)'}` };
332|      const r = resolve(sources.chart, e.citation);
333|      if (!r.ok) return { ...base, status: r.status, reason: r.reason };
334|      const q = checkQuote(r.entry, e.quote);
335|      if (!q.ok) return { ...base, status: q.status, reason: q.reason };
336|      return { ...base, status: 'verified', reason: 'verified: quote found in the cited entry', [VERIFIED]: true };
337|    } catch (error: unknown) {
338|      return { ...base, status: 'error', reason: `error: ${error instanceof Error ? error.message : String(error)}` };
339|    }
340|  });
341|
342|  const criteria: Record<string, 'verified' | 'unverified'> = {};
343|  for (const c of sources.criteria) criteria[c.id] = evidence.some(e => e.status === 'verified' && e.criterion === c.id) ? 'verified' : 'unverified';
344|
345|  const tally = (status: SentenceStatus) => sentences.filter(s => s.status === status).length;
346|  const counts = {
347|    sentences: sentences.length,
348|    verified: tally('verified'),
349|    unresolved: tally('unresolved'),
350|    refuted: tally('refuted'),
351|    needsCitation: tally('needs-citation'),
352|    error: tally('error'),
353|    evidence: evidence.length,
354|    evidenceVerified: evidence.filter(e => e.status === 'verified').length,
355|  };
356|  const errored = sentences.some(s => s.status === 'error') || evidence.some(e => e.status === 'error');
357|
358|  if (!appeal.warranted) {
359|    return { litmus: LITMUS_VERSION, verdict: 'declined', reasons: [], errored, declinedReason: appeal.reason ?? 'no reason given', sentences, evidence, criteria, counts, inputHash };
360|  }
361|
362|  const reasons: string[] = [];
363|  if (sentences.length === 0) reasons.push('no cited sentences: a warranted draft with nothing to verify is blocked');
364|  for (const c of sources.criteria) if (criteria[c.id] === 'unverified') reasons.push(`criterion ${c.id} has no verified evidence`);
365|  for (const s of sentences) if (s.status !== 'verified') reasons.push(`sentence ${s.index} ${s.status}: ${s.reason}`);
366|  for (const e of evidence) if (e.status === 'error') reasons.push(`evidence ${e.index} error: ${e.reason}`);
367|
368|  return { litmus: LITMUS_VERSION, verdict: reasons.length > 0 ? 'blocked' : 'pass', reasons, errored, sentences, evidence, criteria, counts, inputHash };
