282|// The verdict block that ends a verbose run: verdict and counts, gate version,
283|// the gate's input hash (sources and draft), and the sources hash (the record
284|// alone, shared with the kept replay of the same case in the viewer).
285|export function verboseVerdict(gate: GateResult, sources: ReturnType<typeof gateSources>): string[] {
286|  const version = /v\d+(?:\.\d+)?/.exec(gate.litmus)?.[0] ?? gate.litmus.slice(0, 20);
287|  const name = gate.verdict.toUpperCase();
288|  const counts = `${gate.counts.verified} of ${gate.counts.sentences} sentences verified`;
289|  const lines = [`verdict ${name}  ${counts}  gate ${version}`];
290|  if (gate.verdict === 'declined' && gate.declinedReason) lines.push(`reason  ${gate.declinedReason}`.slice(0, 140));
291|  for (const r of gate.reasons) lines.push(`reason  ${r}`.slice(0, 140));
292|  lines.push(`input hash    ${gate.inputHash}`);
293|  lines.push(`sources hash  ${sourcesHash(sources)}`);
294|  return lines;
295|}
