393|    try {
394|      r = opts.agentic ? await provider.proposeAgentic!(agenticRequest({ transcript, user: text })) : await provider.propose(plainRequest({ transcript, user: text }));
395|    } catch (error: unknown) {
396|      const status = (error as { status?: number }).status;
397|      const kind = error instanceof Error ? error.constructor.name : 'Error';
398|      repairs.push({ turn, reasons, sent: text, stopReason: null, latencyMs: 0, usage: EMPTY_USAGE, costUsd: 0, toolCalls: 0, error: `request failed: ${kind}${status ? ` (HTTP ${status})` : ''}` });
