437|export async function mapWithConcurrency<T, R>(items: readonly T[], limit: number, fn: (item: T, index: number) => Promise<R>): Promise<R[]> {
438|  const out: R[] = new Array(items.length);
439|  let next = 0;
440|  const worker = async (): Promise<void> => {
441|    while (next < items.length) {
442|      const i = next++;
443|      out[i] = await fn(items[i]!, i);
444|    }
445|  };
446|  await Promise.all(Array.from({ length: Math.max(1, Math.min(limit, items.length)) }, worker));
447|  return out;
448|}
