1|// The output contract for the appeal-drafting proposer. Flat on purpose: the
2|// Meta Model API rejects recursive schemas and caps nesting at 10 levels.
3|//
4|// Version 2 (Oct 27): every sentence and every piece of evidence carries a
5|// verbatim quote from the cited chart entry. The gate checks the quote is
6|// really there and that the sentence's numbers come from an admissible source.
7|// No resemblance scoring, no keyword list: the evidence is the clinician's own
8|// words, and the physician reviews criterion, quote, and sentence side by side.
9|import { z } from 'zod';
10|
11|// The citation id pattern lives in its own module so the gate (and the viewer's
12|// browser bundle) can import it without pulling in zod.
13|export { CITATION_ID } from './citation.js';
14|import { CITATION_ID } from './citation.js';
15|
16|export const APPEAL_SCHEMA = {
17|  type: 'object',
18|  additionalProperties: false,
19|  required: ['warranted', 'reason', 'evidence', 'sentences'],
20|  properties: {
21|    warranted: {
22|      type: 'boolean',
23|      description: 'true only when the chart supports an appeal of this denial under every listed criterion; false means do not appeal',
24|    },
25|    reason: {
26|      type: 'string',
27|      description: 'when warranted is false, one sentence naming the criterion the chart cannot support or why the denial is not a medical-necessity question; empty string when warranted',
28|    },
29|    evidence: {
30|      type: 'array',
31|      description: 'for each payer criterion the chart supports, one or more items naming the criterion id, the chart entry id, and a verbatim quote from that entry that supports it',
32|      items: {
33|        type: 'object',
34|        additionalProperties: false,
35|        required: ['criterion', 'citation', 'quote'],
36|        properties: {
37|          criterion: { type: 'string', description: 'the criterion id, e.g. crit-2' },
38|          citation: { type: 'string', description: 'the chart entry id the quote comes from, e.g. note-012' },
39|          quote: { type: 'string', description: 'at least two words copied exactly from the text of that entry, no paraphrase' },
40|        },
41|      },
42|    },
43|    sentences: {
44|      type: 'array',
45|      description: 'the appeal, one sentence per item, in order; empty when warranted is false',
46|      items: {
47|        type: 'object',
48|        additionalProperties: false,
49|        required: ['text', 'citation', 'quote'],
50|        properties: {
51|          text: { type: 'string', description: 'one sentence of the appeal in your own words' },
52|          citation: { type: 'string', description: 'the id of the single chart entry this sentence rests on, e.g. note-012' },
53|          quote: { type: 'string', description: 'at least two words copied exactly from the text of that entry that back this sentence; every number in the sentence must appear in the quote, the payer criteria, or the denial' },
54|        },
55|      },
56|    },
57|  },
58|} as const;
59|
60|// Lenient where a model is sloppy (null for an unused string, a missing array,
61|// a blank placeholder sentence), strict where the gate depends on structure.
62|// Citation ids are not validated here: the gate resolves them, and it has to
63|// see a hallucinated id to count it.
64|const str = z.string().nullish().transform(v => (v ?? '').trim());
65|const evidenceSchema = z.object({ criterion: str, citation: str, quote: str });
66|const sentenceSchema = z.object({ text: str, citation: str, quote: str });
67|
68|const appealSchema = z
69|  .object({
70|    warranted: z.boolean(),
71|    reason: str,
72|    evidence: z.array(evidenceSchema).nullish().transform(v => v ?? []),
73|    sentences: z.array(sentenceSchema).nullish().transform(v => v ?? []),
74|  })
75|  .transform(a => ({
76|    warranted: a.warranted,
77|    ...(a.reason ? { reason: a.reason } : {}),
78|    evidence: a.evidence,
79|    sentences: a.sentences.filter(s => s.text.length > 0),
80|  }));
81|
82|export type Appeal = z.infer<typeof appealSchema>;
83|export type Sentence = Appeal['sentences'][number];
84|export type Evidence = Appeal['evidence'][number];
85|export type ParsedAppeal = { ok: true; appeal: Appeal } | { ok: false; error: string };
86|
87|// Errors never echo the model text: on real runs that text is a draft about a
88|// patient, and the harness log is not the place for it.
89|export function parseAppeal(text: string): ParsedAppeal {
90|  let raw: unknown;
91|  try {
92|    raw = JSON.parse(text);
93|  } catch {
94|    return { ok: false, error: 'draft is not valid JSON' };
95|  }
96|  const result = appealSchema.safeParse(raw);
97|  if (!result.success) {
98|    const issue = result.error.issues[0];
99|    return { ok: false, error: `draft failed the contract at ${issue?.path.join('.') || 'root'}: ${issue?.message ?? 'unknown'}` };
100|  }
101|  return { ok: true, appeal: result.data };
102|}
103|
104|// --- the advisor -------------------------------------------------------------
105|// A second, visible opinion beside each criterion: does the quoted evidence,
106|// read literally, satisfy the criterion? It never feeds the gate. The gate
107|// answers whether a statement is in the record; the advisor answers whether
108|// the record satisfies the criterion, which is interpretation, and so it is
109|// shown with the model's name beside the criterion for the physician to weigh.
110|
111|export const ADVICE_SCHEMA = {
112|  type: 'object',
113|  additionalProperties: false,
114|  required: ['items'],
115|  properties: {
116|    items: {
117|      type: 'array',
118|      description: 'one item per payer criterion, in the order given',
119|      items: {
120|        type: 'object',
121|        additionalProperties: false,
122|        required: ['criterion', 'verdict', 'why'],
123|        properties: {
124|          criterion: { type: 'string', description: 'the criterion id, e.g. crit-2' },
125|          verdict: { type: 'string', enum: ['supports', 'partial', 'silent'], description: 'supports: the quotes establish every element of the criterion; partial: the quotes address some elements and not others; silent: the quotes do not address the criterion' },
126|          why: { type: 'string', description: 'one sentence naming which element the quotes establish or lack; use only the quotes, add no facts' },
127|        },
128|      },
129|    },
130|  },
131|} as const;
132|
133|const adviceSchema = z.object({
134|  items: z.array(z.object({
135|    criterion: z.string(),
136|    verdict: z.enum(['supports', 'partial', 'silent']),
137|    why: z.string().default(''),
138|  })).default([]),
139|});
140|export type Advice = z.infer<typeof adviceSchema>;
141|export type ParsedAdvice = { ok: true; advice: Advice } | { ok: false; error: string };
142|
143|export function parseAdvice(text: string): ParsedAdvice {
144|  let raw: unknown;
145|  try {
146|    raw = JSON.parse(text);
147|  } catch {
148|    return { ok: false, error: 'advice is not valid JSON' };
149|  }
150|  const result = adviceSchema.safeParse(raw);
151|  if (!result.success) {
152|    const issue = result.error.issues[0];
153|    return { ok: false, error: `advice failed the contract at ${issue?.path.join('.') || 'root'}: ${issue?.message ?? 'unknown'}` };
154|  }
155|  return { ok: true, advice: result.data };
156|}

