1|// What the gate may treat as admissible for a case: the chart, the payer's
2|// criteria, the denial's own text, and the stated case facts. One function,
3|// shared by the harness (src/harness.ts), the re-gate and mutation scripts,
4|// and the viewer's in-browser recheck (viewer/src/gatecheck.ts), so the gate a
5|// reader runs in the page is given exactly what the harness gave it. The
6|// parameter is structural: a synthetic case and the viewer's case shape both fit.
7|import type { GateSources } from './litmus.js';
8|import { sha256Hex } from './hash.js';
9|
10|export interface GateCase {
11|  chart: { id: string; date?: string; kind?: string; text: string }[];
12|  criteria: { id: string; text: string }[];
13|  denial: { carc: string; rarc?: string; text: string; dateOfService: string; serviceEnd?: string };
14|  patient: { alias: string; age: number; sex: string };
15|  procedure: { code: string; codeSystem: string; description: string };
16|  payer: { name: string; planType: string };
17|}
18|
19|// A hash of the admissible sources alone: the chart, the criteria, the denial,
20|// and the case facts, with no draft in it. The gate's inputHash covers the draft
21|// too, so two live runs of one case never share it; this one they do, which is
22|// how a live run in a terminal is shown to be on the same record as a kept
23|// replay (harness --verbose, and the viewer's case header).
24|export function sourcesHash(s: GateSources): string {
25|  return sha256Hex(JSON.stringify({ chart: s.chart, criteria: s.criteria, denial: s.denial, facts: s.facts ?? [] }));
26|}
27|
28|export function gateSources(c: GateCase): GateSources {
29|  return {
30|    chart: c.chart,
31|    criteria: c.criteria,
32|    denial: [c.denial.text, `CARC ${c.denial.carc}`, c.denial.dateOfService, ...(c.denial.serviceEnd ? [c.denial.serviceEnd] : []), ...(c.denial.rarc ? [c.denial.rarc] : [])],
33|    facts: [`Patient ${c.patient.alias}, ${c.patient.age} year old ${c.patient.sex}`, `${c.procedure.codeSystem} ${c.procedure.code} ${c.procedure.description}`, `${c.payer.name}, ${c.payer.planType}`],
34|  };
35|}

