1|// policy_status: a third tool for the agentic proposer, a live query against
2|// CHART (chart.hemeehr.com), the author's pre-existing coverage index. It is a
3|// new integration of a hosted API, in the same category as the model call,
4|// and it is labeled as a prior-work data source wherever its answer appears.
5|//
6|// What it returns: when the named authority's coverage material last changed
7|// and was last checked, from the census-wide coverage index. It never returns
8|// policy text. The synthetic payers here are fictional, so the lookup is keyed
9|// on a real authority id (CMS by default) and the procedure code, and no
10|// patient data is sent: the request carries an authority id, a code, and a date.
11|import type { ToolCall, ToolDefinition, ToolOutcome } from './provider.js';
12|
13|export const CHART_BASE_URL = 'https://chart.hemeehr.com';
14|export const DEFAULT_AUTHORITY = 'cms';
15|
16|export const POLICY_STATUS_TOOL: ToolDefinition = {
17|  name: 'policy_status',
18|  description:
19|    'Live query against CHART, a pre-existing coverage index of US payer policy. Returns when the named authority\'s coverage material last changed and was last checked, so you can say whether the criteria you were given are current. It does not return policy text: the criteria in this request are the criteria. Use authority "cms" unless told otherwise.',
20|  inputSchema: {
21|    type: 'object',
22|    required: ['code', 'date_of_service', 'why'],
23|    properties: {
24|      authority: { type: 'string', description: 'CHART authority id, e.g. cms, ma-uhc, cigna; defaults to cms' },
25|      code: { type: 'string', description: 'the CPT, HCPCS, or ICD-10 code on the denial' },
26|      date_of_service: { type: 'string', description: 'YYYY-MM-DD' },
27|      // The API returns only redacted thinking, so the model states its reason here; the trace and the viewer show it.
28|      why: { type: 'string', description: 'one sentence: what you want to learn from this query and why now' },
29|    },
30|    additionalProperties: false,
31|  },
32|};
33|
34|export interface AuthorityStatus {
35|  id: string;
36|  name?: string;
37|  lastChange?: string;
38|  lastCheck?: string;
39|  policies?: number;
40|  documents?: number;
41|}
42|
43|const KEYS = {
44|  name: ['authority', 'name', 'label'],
45|  lastChange: ['last_changed', 'last_change', 'lastChange', 'last-change', 'changed_at'],
46|  lastCheck: ['oldest_check', 'oldest_live_check', 'oldestLiveCheck', 'last_check', 'lastCheck', 'last-check', 'checked_at', 'last_verified'],
47|  policies: ['policies', 'policy_count'],
48|  documents: ['documents', 'document_count'],
49|};
50|
51|function pick(row: Record<string, unknown>, names: string[]): unknown {
52|  for (const n of names) if (row[n] !== undefined && row[n] !== null && row[n] !== '') return row[n];
53|  return undefined;
54|}
55|
56|// The index (confirmed live Oct 28, 2026) is {generated_at, corpus, authorities:[{id, name,
57|// kind, documents, cataloged, policies, last_changed, oldest_check, endpoints}], policies:[...]}.
58|// The finder stays lenient so a renamed field degrades to 'not reported' rather than a failure.
59|function rows(body: unknown): Record<string, unknown>[] {
60|  if (Array.isArray(body)) return body.filter((x): x is Record<string, unknown> => !!x && typeof x === 'object');
61|  if (body && typeof body === 'object') {
62|    const o = body as Record<string, unknown>;
63|    for (const k of ['authorities', 'rows', 'index', 'items', 'data']) if (Array.isArray(o[k])) return rows(o[k]);
64|    for (const v of Object.values(o)) if (Array.isArray(v) && v.some(x => x && typeof x === 'object' && 'id' in (x as object))) return rows(v);
65|  }
66|  return [];
67|}
68|
69|export function parseAuthorityStatus(body: unknown, authority: string): AuthorityStatus | null {
70|  const want = authority.trim().toLowerCase();
71|  const row = rows(body).find(r => String(r['id'] ?? '').toLowerCase() === want || String(r['authority_id'] ?? '').toLowerCase() === want);
72|  if (!row) return null;
73|  // Timestamps come back as ISO instants; the model only needs the day.
74|  const str = (v: unknown) => (v === undefined ? undefined : String(v).replace(/T\d\d:\d\d:\d\d(\.\d+)?Z$/, ''));
75|  const num = (v: unknown) => (typeof v === 'number' ? v : typeof v === 'string' && v.trim() !== '' && Number.isFinite(Number(v)) ? Number(v) : undefined);
76|  const out: AuthorityStatus = { id: authority };
77|  const name = str(pick(row, KEYS.name)); if (name) out.name = name;
78|  const lc = str(pick(row, KEYS.lastChange)); if (lc) out.lastChange = lc;
79|  const lk = str(pick(row, KEYS.lastCheck)); if (lk) out.lastCheck = lk;
80|  const p = num(pick(row, KEYS.policies)); if (p !== undefined) out.policies = p;
81|  const d = num(pick(row, KEYS.documents)); if (d !== undefined) out.documents = d;
82|  return out;
83|}
84|
85|export interface PolicyStatusOptions {
86|  apiKey: string;
87|  baseURL?: string;
88|  fetch?: typeof fetch;
89|  timeoutMs?: number;
90|  cache?: boolean; // default true: one metered query per authority for the life of this executor
91|}
92|
93|const LABEL = 'live CHART query, prior-work data source';
94|
95|export function policyStatusExecutor(options: PolicyStatusOptions): (call: ToolCall) => Promise<ToolOutcome | null> {
96|  const doFetch = options.fetch ?? fetch;
97|  const base = (options.baseURL ?? CHART_BASE_URL).replace(/\/$/, '');
98|  // The index is metered per request and its answer (when an authority's
99|  // material last changed) is the same for every case in a run: the live
100|  // endpoint returns the whole authority table whatever code is passed. So the
101|  // memo is keyed on the authority alone and one executor shared across a run
102|  // makes one metered query per authority. Only successful answers are kept; a
103|  // 402 or an outage is retried on the next call.
104|  const memo = new Map<string, ToolOutcome>();
105|  const query = async (authority: string, code: string, asOf: string): Promise<ToolOutcome> => {
106|    let res: Response;
107|    try {
108|      res = await doFetch(`${base}/v1/coverage-index?code=${encodeURIComponent(code)}&as_of=${encodeURIComponent(asOf)}`, {
109|        headers: { authorization: `Bearer ${options.apiKey}`, accept: 'application/json' },
110|        signal: AbortSignal.timeout(options.timeoutMs ?? 15_000),
111|      });
112|    } catch (error: unknown) {
113|      return { ok: false, content: `CHART unreachable: ${error instanceof Error ? error.constructor.name : 'Error'}. Proceed without it; the criteria you were given still apply.`, live: true, note: 'CHART unreachable' };
114|    }
115|    if (!res.ok) {
116|      const why = res.status === 402 || res.status === 401 ? 'key missing, unknown, or plan required' : 'request failed';
117|      return { ok: false, content: `CHART returned HTTP ${res.status}: ${why}. Proceed without it; the criteria you were given still apply.`, live: true, note: `CHART HTTP ${res.status}` };
118|    }
119|    let body: unknown;
120|    try {
121|      body = await res.json();
122|    } catch {
123|      return { ok: false, content: 'CHART answered with something other than JSON', live: true, note: 'CHART bad body' };
124|    }
125|    const status = parseAuthorityStatus(body, authority);
126|    if (!status) return { ok: false, content: `CHART has no authority "${authority}" in its coverage index`, live: true, note: `no authority ${authority}` };
127|    const parts = [
128|      `CHART coverage index, authority ${status.name ? `${status.name} (${status.id})` : status.id}`,
129|      status.lastChange ? `last change ${status.lastChange}` : 'last change not reported',
130|      status.lastCheck ? `last live check ${status.lastCheck}` : 'last check not reported',
131|      ...(status.policies !== undefined ? [`${status.policies} policies indexed`] : []),
132|      `queried for ${code} as of ${asOf}`,
133|      `${LABEL}; this is corpus freshness, not policy text, and the criteria in this request are unchanged`,
134|    ];
135|    const note = `${status.id}: criteria last changed ${status.lastChange ?? 'unknown'}, last checked ${status.lastCheck ?? 'unknown'}`;
136|    return { ok: true, content: parts.join('. ') + '.', live: true, note };
137|  };
138|  return async call => {
139|    if (call.name !== 'policy_status') return null;
140|    const authority = String(call.input['authority'] ?? DEFAULT_AUTHORITY).trim().toLowerCase() || DEFAULT_AUTHORITY;
141|    // Models write codes the way denials print them: "MS-DRG 871", "CMG 0104",
142|    // "HIPPS KDOB1". The index wants the bare code.
143|    const code = String(call.input['code'] ?? '').trim().replace(/^(?:MS-?DRG|DRG|CMG|HIPPS|CPT|HCPCS|ICD-?10(?:-CM)?)[:\s]*/i, '').replace(/\s+/g, '');
144|    const asOf = String(call.input['date_of_service'] ?? '').trim();
145|    if (!/^[A-Za-z0-9.-]{1,12}$/.test(code)) return { ok: false, content: 'policy_status needs the procedure or diagnosis code on the denial', live: true, note: 'bad code' };
146|    if (!/^\d{4}-\d{2}-\d{2}$/.test(asOf)) return { ok: false, content: 'policy_status needs date_of_service as YYYY-MM-DD', live: true, note: 'bad date' };
147|    const key = authority;
148|    const hit = options.cache !== false ? memo.get(key) : undefined;
149|    if (hit) return { ...hit, content: hit.content.replace(/queried for \S+ as of \d{4}-\d{2}-\d{2}/, `queried for ${code} as of ${asOf}`), note: `${hit.note} (cached this run)` };
150|    const out = await query(authority, code, asOf);
151|    if (out.ok && options.cache !== false) memo.set(key, out);
152|    return out;
153|  };
154|}

