1|// The gate, in the browser. Once a replay has reached its verdict, a reader can
2|// change a sentence (its words, its quote, or its citation) and have the same
3|// gate the harness ran re-check it against the same case: the same module
4|// (src/litmus.ts), the same admissible sources (src/sources.ts), bundled into
5|// app.js. Nothing is saved: the stored result and its verdict do not change,
6|// and the edit lives only in the page. This is the spike-in of section 2.7 made
7|// into a control a judge can turn by hand.
8|import { checkSentence, LITMUS_VERSION, type SentenceRecord, type SentenceStatus } from '../../src/litmus.js';
9|import { gateSources } from '../../src/sources.js';
10|import type { ViewerCase } from './replay.js';
