1|// The gate, in the browser. Once a replay has reached its verdict, a reader can
2|// change a sentence (its words, its quote, or its citation) and have the same
3|// gate the harness ran re-check it against the same case: the same module
4|// (src/litmus.ts), the same admissible sources (src/sources.ts), bundled into
5|// app.js. Nothing is saved: the stored result and its verdict do not change,
6|// and the edit lives only in the page. This is the spike-in of section 2.7 made
7|// into a control a judge can turn by hand.
8|import { checkSentence, LITMUS_VERSION, type SentenceRecord, type SentenceStatus } from '../../src/litmus.js';
9|import { gateSources } from '../../src/sources.js';
10|import type { ViewerCase } from './replay.js';
11|
12|export interface EditedSentence { text: string; citation: string; quote: string }
13|
14|export interface Recheck {
15|  status: SentenceStatus;
16|  reason: string;
17|  missing?: string[];
18|  alsoCite?: string[];
19|  gate: string; // the gate version that judged the edit
20|}
21|
22|export function recheck(c: ViewerCase, edited: EditedSentence): Recheck {
23|  const record: SentenceRecord = checkSentence(gateSources(c), { text: edited.text, citation: edited.citation, quote: edited.quote });
24|  return {
25|    status: record.status,
26|    reason: record.reason,
27|    ...(record.missing ? { missing: record.missing } : {}),
28|    ...(record.alsoCite ? { alsoCite: record.alsoCite } : {}),
29|    gate: LITMUS_VERSION,
30|  };
31|}
32|
33|export function recheckLabel(status: SentenceStatus): string {
34|  return status === 'needs-citation' ? 'needs citation' : status;
35|}
