236|  for (const li of ui.entries.children) {
237|    const el = li as HTMLElement;
238|    const id = el.dataset['id'] ?? '';
239|    const next = id === state.open ? 'open' : state.read.includes(id) ? 'read' : 'dim';
240|    if (el.dataset['state'] !== next) el.dataset['state'] = next;
241|    const tag = el.querySelector('.tag') as HTMLElement;
242|    const s = readAt.get(id);
243|    const label: string = s?.kind === 'read' ? `${s.tool}${s.live ? ', live' : ''}${s.repair ? `, repair turn ${s.repair}` : ''}` : state.read.includes(id) ? 'cited' : '';
244|    if (tag.textContent !== label) tag.textContent = label;
245|    tag.classList.toggle('live', s?.kind === 'read' && s.live === true);
246|    tag.classList.toggle('repair', s?.kind === 'read' && s.repair !== undefined);
247|  }
248|  // state.open is a citation the model wrote; escape it so a stray quote or
249|  // bracket cannot throw inside render and stall playback.
250|  const open = state.open ? ui.entries.querySelector<HTMLElement>(`[data-id="${CSS.escape(state.open)}"]`) : null;
251|  open?.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
252|  ui.chartMeta.textContent = `${state.counters.chartSize} entries, ${state.read.length} read`;
253|  renderWhy(state);
254|}
255|
256|// The model's reason for the read it is making, typed out under the chart
257|// header while the entry lights (the API returns only redacted thinking, so
258|// the reason is the one the model wrote into the tool call). Typed once per
259|// visit to the step; a re-render at the same cursor leaves it alone.
260|let whyTimers: number[] = [];
261|let whyKey = '';
262|function renderWhy(state: ReplayState): void {
263|  const why = state.why;
264|  const key = why ? `${session.rendered.file ?? ''}|${session.result?.caseId ?? ''}|${state.cursor}` : '';
265|  if (!why) {
266|    if (!ui.chartWhy.hidden) { ui.chartWhy.hidden = true; ui.chartWhy.replaceChildren(); }
267|    for (const t of whyTimers) window.clearTimeout(t);
268|    whyTimers = []; whyKey = '';
269|    return;
270|  }
271|  if (key === whyKey && !ui.chartWhy.hidden) return;
272|  for (const t of whyTimers) window.clearTimeout(t);
273|  whyTimers = []; whyKey = key;
274|  const lbl = text('span', 'lbl', why.entryId ? `why ${why.entryId}` : why.live ? 'why the live query' : 'why');
275|  const val = text('span', 'val', '');
276|  ui.chartWhy.replaceChildren(lbl, val);
277|  ui.chartWhy.hidden = false;
278|  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
279|  if (reduced) { val.textContent = why.text; return; }
280|  const chars = [...why.text];
281|  const cursor = text('span', 'cursor', '');
282|  val.append(cursor);
283|  let n = 0;
284|  const tick = (): void => {
285|    const ch = chars[n];
286|    if (ch !== undefined) cursor.before(document.createTextNode(ch));
287|    n += 1;
288|    if (n < chars.length) whyTimers.push(window.setTimeout(tick, Math.max(8, TYPE_CHAR_MS / 3)));
289|    else whyTimers.push(window.setTimeout(() => cursor.remove(), 600));
290|  };
291|  tick();
292|}
293|
294|function renderCriteria(state: ReplayState): void {
295|  renderStrip(state);
296|  ui.criteria.replaceChildren(...state.criteria.map(k => {
297|    const li = document.createElement('li');
298|    li.className = 'criterion';
299|    li.dataset['status'] = k.status;
300|    const box = text('span', 'box', k.status === 'verified' ? '✓' : k.status === 'unverified' ? '⚠' : '');
301|    const t = document.createElement('div');
302|    t.className = 'text';
303|    t.append(text('span', 'cid', k.id), k.text);
304|    li.append(box, t);
305|    if (k.evidence.length > 0) {
306|      const ev = document.createElement('div');
307|      ev.className = 'evidence';
308|      for (const e of k.evidence) {
309|        const q = document.createElement('div');
310|        q.className = 'quote';
311|        q.dataset['status'] = e.status;
312|        q.append(text('span', '', `“${e.quote}”`), text('span', 'src', e.citation));
313|        if (e.status !== 'verified') q.append(text('span', 'why', e.reason));
314|        ev.append(q);
315|      }
316|      li.append(ev);
317|    } else if (k.status === 'unverified') {
318|      li.append(text('div', 'none', '⚠ No evidence found in the chart for this criterion.'));
319|    }
320|    if (k.advice) {
321|      // The advisor's opinion: interpretation, named, beside the criterion, never a gate input.
322|      const a = document.createElement('div');
323|      a.className = 'advice';
324|      a.dataset['verdict'] = k.advice.verdict;
325|      const glyph = k.advice.verdict === 'supports' ? '✓' : k.advice.verdict === 'partial' ? '◐' : '◌';
326|      a.append(text('span', 'advice-tag', `advisor ${k.advice.model}`), text('span', 'advice-verdict', `${glyph} ${k.advice.verdict}`), text('span', 'advice-why', k.advice.why));
327|      li.append(a);
328|    }
329|    return li;
330|  }));
331|  const met = state.criteria.filter(k => k.status === 'verified').length;
332|  ui.critMeta.textContent = `${met} of ${state.criteria.length} with verified evidence`;
333|  ui.lookups.replaceChildren(...state.lookups.map(l => {
334|    const li = document.createElement('li');
335|    if (l.live) li.append(text('span', 'live-tag', 'live CHART query, prior-work data source'));
336|    li.append(text('span', '', `${l.tool}: ${l.note}`));
337|    return li;
338|  }));
339|}
340|
341|// The live query strip. The answer types out once per visit to the step; a
342|// re-render at the same cursor leaves it alone.
343|let stripTimers: number[] = [];
344|let stripKey = '';
345|function renderStrip(state: ReplayState): void {
346|  const strip = state.strip;
347|  const key = strip ? `${session.rendered.file ?? ''}|${session.result?.caseId ?? ''}|${state.cursor}` : '';
348|  if (!strip) {
349|    if (!ui.strip.hidden) { ui.strip.hidden = true; ui.criteria.hidden = false; ui.lookups.hidden = false; }
350|    for (const t of stripTimers) window.clearTimeout(t);
351|    stripTimers = []; stripKey = '';
352|    return;
353|  }
354|  if (key === stripKey && !ui.strip.hidden) return;
355|  for (const t of stripTimers) window.clearTimeout(t);
356|  stripTimers = []; stripKey = key;
357|  const node = (cls: string, label: string, value: string) => {
358|    const n = document.createElement('div');
359|    n.className = `node ${cls}`;
360|    n.append(text('span', 'lbl', label), text('span', 'val', value));
361|    return n;
362|  };
363|  const arrow = () => text('span', 'arrow', '→');
364|  const answer = node('answer', 'answer', '');
365|  const q = text('div', 'q', '');
366|  q.append(text('span', 'live-tag', 'live CHART query, prior-work data source'), text('span', '', strip.question));
367|  ui.strip.replaceChildren(node('payer', 'payer', strip.payer), arrow(), node('authority', 'authority asked', strip.authority), arrow(), node('index', 'index', strip.index), arrow(), answer, q);
368|  ui.criteria.hidden = true;
369|  ui.lookups.hidden = true; // the strip carries the query's line; the list returns with the criteria
370|  ui.strip.hidden = false;
371|  const val = answer.querySelector<HTMLElement>('.val')!;
372|  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
373|  if (reduced) { val.textContent = strip.answer; return; }
374|  // Type the answer after the nodes have arrived, at the typing pace.
375|  const chars = [...strip.answer];
376|  const cursor = text('span', 'cursor', '');
377|  val.append(cursor);
378|  let n = 0;
379|  const tick = (): void => {
380|    const ch = chars[n];
381|    if (ch !== undefined) cursor.before(document.createTextNode(ch));
382|    n += 1;
383|    if (n < chars.length) stripTimers.push(window.setTimeout(tick, TYPE_CHAR_MS));
384|    else stripTimers.push(window.setTimeout(() => cursor.remove(), 900));
385|  };
386|  stripTimers.push(window.setTimeout(tick, 560));
387|}
388|
389|// A sentence as the gate judged it: text, citation, quote, status, reason. Kept
390|// per rendered row so the in-browser editor can restore it after an edit.
391|interface SentenceOriginal { text: string; citation: string; quote: string; status: SentenceState['status']; reason: string }
392|const originals = new WeakMap<HTMLElement, SentenceOriginal>();
393|
394|function stampText(status: SentenceState['status']): string {
395|  return `${status === 'verified' ? '✓' : status === 'needs-citation' ? '◐' : '⚠'} ${recheckLabel(status)}`;
396|}
397|
398|function fillWhy(why: HTMLElement, s: SentenceOriginal, previous?: { status: SentenceState['status']; reason: string }): void {
399|  why.className = s.status === 'verified' ? 'why' : 'why bad';
400|  why.replaceChildren();
401|  // A re-stamped sentence shows its first stamp and the gate's reason, then the stamp it carries now.
402|  if (previous) {
403|    const first = text('div', 'restamp', '');
404|    first.dataset['status'] = previous.status;
405|    first.append(text('b', '', `first ${stampText(previous.status)}`), text('span', '', ` ${previous.reason}`), text('span', 'then', ` \u2192 after the repair turn ${stampText(s.status)}`));
406|    why.append(first);
407|  }
408|  if (s.status === 'verified') {
409|    why.append(text('b', '', 'verified '), text('span', 'src', `${s.citation}: `), (() => { const q = document.createElement('q'); q.textContent = s.quote; return q; })());
410|  } else {
411|    why.append(text('b', '', `${recheckLabel(s.status)} `), text('span', '', `${s.reason} (cited ${s.citation})`));
412|  }
413|}
414|
415|function renderSentences(state: ReplayState): void {
416|  const named = state.verdict?.kind === 'verdict' ? state.verdict.blockedSentence : undefined;
417|  const existing = ui.sentences.children.length;
418|  // Append only the new sentences so earlier ones keep still and the new one animates in.
419|  if (existing > state.sentences.length) ui.sentences.replaceChildren();
420|  // A repair turn re-stamps a sentence in place: the row stays, its stamp and
421|  // reason change, and the first stamp is kept above the new one.
422|  for (let i = 0; i < Math.min(ui.sentences.children.length, state.sentences.length); i++) {
423|    const li = ui.sentences.children[i] as HTMLElement;
424|    const s = state.sentences[i]!;
425|    const o = originals.get(li);
426|    if (!o || li.dataset['editing'] || (o.status === s.status && o.reason === s.reason && o.text === s.text && o.citation === s.citation && o.quote === s.quote)) continue;
427|    const original: SentenceOriginal = { text: s.text, citation: s.citation, quote: s.quote, status: s.status, reason: s.reason };
428|    originals.set(li, original);
429|    li.dataset['status'] = s.status;
430|    li.classList.add('restamped');
431|    li.querySelector<HTMLElement>('.text')!.textContent = s.text;
432|    li.querySelector<HTMLElement>('.stamp')!.textContent = stampText(s.status);
433|    fillWhy(li.querySelector<HTMLElement>('.why')!, original, s.previous);
434|  }
435|  for (const s of state.sentences.slice(ui.sentences.children.length)) {
436|    const li = document.createElement('li');
437|    li.className = 'sentence';
438|    li.dataset['status'] = s.status;
439|    li.dataset['index'] = String(s.index);
440|    const original: SentenceOriginal = { text: s.text, citation: s.citation, quote: s.quote, status: s.status, reason: s.reason };
441|    originals.set(li, original);
442|    const why = document.createElement('div');
443|    fillWhy(why, original, s.previous);
444|    if (s.previous) li.classList.add('restamped');
445|    const edit = document.createElement('button');
446|    edit.type = 'button';
447|    edit.className = 'edit';
448|    edit.textContent = EDIT_BUTTON;
449|    edit.title = EDIT_HELP;
450|    li.append(text('div', 'text', s.text), text('span', 'stamp', stampText(s.status)), why, edit);
451|    ui.sentences.append(li);
452|  }
453|  // The gate can be tested by hand once the replay has reached its verdict.
454|  ui.sentences.dataset['editable'] = state.verdict ? 'true' : 'false';
455|  for (const li of ui.sentences.children) (li as HTMLElement).classList.toggle('named', named !== undefined && (li as HTMLElement).dataset['index'] === String(named));
456|  ui.sentences.lastElementChild?.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
457|  ui.draftEmpty.hidden = state.sentences.length > 0 || state.verdict !== null;
458|  ui.draftMeta.textContent = state.counters.sentencesTotal > 0 ? `${state.counters.sentencesVerified} of ${state.counters.sentencesTotal} sentences verified` : '';
459|}
460|
461|// The gate in the browser: the reader edits a sentence, its quote, or its
462|// citation, and the same gate the harness ran re-checks it against the same
463|// case. Nothing is saved; restore puts the stored record back.
464|function openEditor(li: HTMLElement): void {
465|  const original = originals.get(li);
466|  const c = session.caseData;
467|  if (!original || !c || li.dataset['editing']) return;
468|  li.dataset['editing'] = 'true';
469|  const textEl = li.querySelector<HTMLElement>('.text')!;
470|  const stamp = li.querySelector<HTMLElement>('.stamp')!;
471|  const why = li.querySelector<HTMLElement>('.why')!;
472|  textEl.replaceChildren();
473|  const sentence = document.createElement('textarea');
474|  sentence.className = 'edit-text';
475|  sentence.value = original.text;
476|  sentence.rows = 3;
477|  sentence.setAttribute('aria-label', 'the sentence');
478|  textEl.append(sentence);
479|
480|  const form = document.createElement('div');
481|  form.className = 'editor';
482|  const quote = document.createElement('textarea');
483|  quote.className = 'edit-quote';
484|  quote.value = original.quote;
485|  quote.rows = 2;
486|  quote.setAttribute('aria-label', 'the quote');
487|  const cite = document.createElement('select');
488|  cite.className = 'edit-cite';
489|  cite.setAttribute('aria-label', 'the cited entry');
490|  for (const e of c.chart) {
491|    const opt = document.createElement('option');
492|    opt.value = e.id;
493|    opt.textContent = `${e.id} · ${e.date} · ${e.kind}`;
494|    opt.selected = e.id === original.citation;
495|    cite.append(opt);
496|  }
497|  const check = document.createElement('button');
498|  check.type = 'button';
499|  check.className = 'btn primary small';
500|  check.textContent = 'check';
