342|export function buildTimeline(result: ViewerResult, c: ViewerCase): Step[] {
343|  const steps: Step[] = [];
344|  const chartIds = new Set(c.chart.map(e => e.id));
345|  const trace = (result.trace ?? []).slice().sort((a, b) => a.step - b.step);
346|
347|  // Tool calls become read and lookup steps; the model's why and the repair
348|  // turn ride along. Returns when the reading ended.
349|  const pushReads = (events: TraceEvent[]): number => {
350|    let ends = 0;
351|    for (const t of events) {
352|      const extra = { ...(t.why ? { why: t.why } : {}), ...(t.repair ? { repair: t.repair } : {}) };
353|      if (t.tool === 'read_entry' && t.entryId && chartIds.has(t.entryId)) {
354|        steps.push({ kind: 'read', entryId: t.entryId, tool: t.tool, live: t.live ?? false, ...(t.note ? { note: t.note } : {}), ...extra, atMs: t.atMs });
355|      } else if (t.tool !== 'read_entry') {
356|        const input = lookupQuestion(t.input);
357|        steps.push({ kind: 'lookup', tool: t.tool, note: t.note ?? (t.ok ? 'ok' : 'failed'), live: t.live ?? false, ...(input ? { input } : {}), ...extra, atMs: t.atMs });
358|      }
359|      ends = Math.max(ends, t.atMs);
360|    }
361|    return ends;
362|  };
363|
364|  let readingEnds = 0;
365|  if (trace.length > 0) {
366|    readingEnds = pushReads(trace.filter(t => !t.repair));
367|  } else {
368|    const ids = citedEntries(result).filter(id => chartIds.has(id));
369|    if (ids.length > 0) steps.push({ kind: 'read-all', entryIds: ids, atMs: 0 });
370|  }
371|
372|  if (result.error && !result.gate) {
373|    steps.push({ kind: 'verdict', verdict: 'error', reasons: [], error: result.error, atMs: result.latencyMs });
374|    return steps;
375|  }
376|  const gate = result.gate;
377|  if (!gate) return steps;
378|
379|  // The gate's records come back in one shot after the model answers; spread
380|  // them across the remaining latency so the replay has a visible rhythm. A
381|  // sentence re-stamped by a repair turn carries its earlier stamp as previous.
382|  type Gate = NonNullable<ViewerResult['gate']>;
383|  const pushGate = (g: Gate, from: number, to: number, previous: Gate | null, repair: number | undefined): void => {
384|    const tail = g.evidence.length + g.sentences.length + 1;
385|    const span = Math.max(0, to - from);
386|    const at = (i: number) => Math.round(from + (span * (i + 1)) / tail);
387|    let i = 0;
388|    for (const e of g.evidence) {
389|      steps.push({ kind: 'evidence', criterion: e.criterion, citation: e.citation, quote: e.quote, status: e.status, reason: e.reason, atMs: at(i++) });
390|    }
391|    for (const s of g.sentences) {
392|      const prev = previous?.sentences.find(p => p.index === s.index);
393|      const changed = prev !== undefined && (prev.status !== s.status || prev.reason !== s.reason || prev.text !== s.text);
394|      steps.push({ kind: 'sentence', index: s.index, text: s.text, citation: s.citation, quote: s.quote, status: s.status, reason: s.reason, ...(changed ? { previous: { status: prev.status, reason: prev.reason } } : {}), ...(repair ? { repair } : {}), atMs: at(i++) });
395|    }
396|    const blocked = g.sentences.find(s => s.status !== 'verified');
397|    steps.push({
398|      kind: 'verdict',
399|      verdict: g.verdict,
400|      reasons: g.reasons,
401|      ...(g.declinedReason ? { declinedReason: g.declinedReason } : {}),
402|      ...(g.verdict === 'blocked' && blocked ? { blockedSentence: blocked.index } : {}),
403|      ...(repair ? { repair } : {}),
404|      atMs: to,
405|    });
406|  };
407|
408|  const repairs = (result.repairs ?? []).filter(r => r.gate);
409|  if (result.firstGate && repairs.length > 0) {
410|    // The first draft, stamped and blocked; then each repair turn: the reasons
411|    // sent, the entries it read, the revised draft re-stamped, its verdict.
412|    const repairLatency = repairs.reduce((n, r) => n + r.latencyMs, 0);
413|    const firstEnd = Math.max(readingEnds, result.latencyMs - repairLatency);
414|    pushGate(result.firstGate, readingEnds, firstEnd, null, undefined);
415|    let t0 = firstEnd;
416|    let previous: Gate = result.firstGate;
417|    repairs.forEach((r, i) => {
418|      const g = r.gate!;
419|      steps.push({ kind: 'repair', turn: r.turn, reasons: r.reasons, sentences: g.sentences.length, atMs: t0 });
420|      const ends = Math.max(t0, pushReads(trace.filter(t => t.repair === r.turn)));
421|      const to = Math.max(ends, i === repairs.length - 1 ? result.latencyMs : t0 + r.latencyMs);
422|      pushGate(g, ends, to, previous, r.turn);
423|      previous = g;
424|      t0 = to;
425|    });
426|  } else {
427|    pushGate(gate, readingEnds, result.latencyMs, null, undefined);
428|  }
429|  if (result.advice && result.advice.items.length > 0) {
430|    steps.push({ kind: 'advice', model: result.advice.model, items: result.advice.items, atMs: result.latencyMs + 1 });
431|  }
432|  return steps;
433|}
