319|export function lookupQuestion(input: Record<string, unknown> | undefined): LookupQuestion | undefined {
320|  if (!input) return undefined;
321|  const authority = String(input['authority'] ?? '').trim().toLowerCase();
322|  const code = String(input['code'] ?? '').trim();
323|  const asOf = String(input['date_of_service'] ?? input['asOf'] ?? '').trim();
324|  if (!authority && !code && !asOf) return undefined;
325|  return { authority: authority || 'cms', code, asOf };
