334|export function lookupStrip(step: Step, c: ViewerCase): LookupStrip | null {
335|  if (step.kind !== 'lookup' || !step.live) return null;
336|  const authorityId = step.input?.authority ?? 'cms';
337|  const answer = step.note.replace(new RegExp(`^${authorityId.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}:\\s*`, 'i'), '');
338|  const question = step.input ? `${step.tool}: ${step.input.code} as of ${step.input.asOf}` : step.tool;
339|  return { payer: c.payer.name, authority: authorityId.toUpperCase(), index: 'CHART coverage index, prior-work data source', question, answer };
