634|  opened: string[]; // entry ids, in the order first read, reads that resolved only
635|  lookups: { tool: string; note: string; live: boolean }[];
636|  sentences: SentenceState[];
637|  verdict: 'pass' | 'blocked' | 'declined' | 'error';
638|  reasons: string[];
639|  declinedReason?: string;
640|  outcomeLabel: string;
641|  costUsd: number;
642|  latencyMs: number;
643|  entriesRead: number;
644|  chartSize: number | null;
645|}
646|
647|export function compareColumns(files: { file: string; data: ResultsFile }[], caseId: string): CompareColumn[] {
648|  const live = files.filter(f => f.data.run.side !== 'payer' && !f.data.run.repair && f.data.results.some(r => (r.trace ?? []).some(t => t.live === true)));
649|  const byModel = new Map<string, { file: string; data: ResultsFile }>();
650|  for (const f of live) {
651|    const key = MODEL_LABELS[f.data.run.model] ?? f.data.run.model;
652|    const current = byModel.get(key);
653|    if (!current || f.data.run.startedAt.localeCompare(current.data.run.startedAt) > 0) byModel.set(key, f);
654|  }
655|  const ordered = [...byModel.values()].sort((a, b) => rank(MODEL_LABELS[a.data.run.model] ?? a.data.run.model) - rank(MODEL_LABELS[b.data.run.model] ?? b.data.run.model));
656|  return ordered.map(f => {
657|    const r = f.data.results.find(x => x.caseId === caseId) ?? null;
658|    const opened: string[] = [];
659|    const lookups: CompareColumn['lookups'] = [];
660|    for (const t of (r?.trace ?? []).slice().sort((a, b) => a.step - b.step)) {
661|      if (t.tool === 'read_entry') { if (t.ok && t.entryId && !opened.includes(t.entryId)) opened.push(t.entryId); }
662|      else lookups.push({ tool: t.tool, note: t.note ?? (t.ok ? 'ok' : 'failed'), live: t.live ?? false });
663|    }
664|    const gate = r?.gate;
665|    return {
666|      file: f.file,
667|      model: f.data.run.model,
668|      label: MODEL_LABELS[f.data.run.model] ?? f.data.run.model,
669|      provider: f.data.run.provider,
670|      startedAt: f.data.run.startedAt,
671|      live: true,
672|      result: r,
673|      opened,
674|      lookups,
675|      sentences: (gate?.sentences ?? []).map(s => ({ index: s.index, text: s.text, citation: s.citation, quote: s.quote, status: s.status, reason: s.reason })),
676|      verdict: gate ? gate.verdict : 'error',
677|      reasons: gate?.reasons ?? [],
678|      ...(gate?.declinedReason ? { declinedReason: gate.declinedReason } : {}),
679|      outcomeLabel: r ? sideText(undefined).outcome(r.outcome) : 'not in this run',
680|      costUsd: r?.costUsd ?? 0,
681|      latencyMs: r?.latencyMs ?? 0,
682|      entriesRead: opened.length,
683|      chartSize: r?.reading?.chartSize ?? null,
684|    };
685|  });
686|}
687|
688|export function formatUsd(n: number): string {
689|  return n >= 1 ? `$${n.toFixed(2)}` : `$${n.toFixed(3)}`;
690|}
691|
692|export function formatSeconds(ms: number): string {
693|  return `${(ms / 1000).toFixed(1)} s`;
694|}
695|
696|// The typing pace, per character, shared by the model's why under the chart
697|// header and the live query strip's answer. The typed opening that once used
698|// it (three lines over the page, Oct 28 to Nov 1) left the page on Nov 1 so a
699|// take opens on the case itself; its words are kept in
700|// assets/video/WALKTHROUGH.md for the script.
701|export const TYPE_CHAR_MS = 36;
702|
703|// The provenance line in the "about this page" panel: what was built this
704|// week and what was pre-existing, as the event rule asks. Plain words, no
705|// exclamation marks; a test holds it to that.
706|export const PROVENANCE_STAMP = "Built this week: everything shown here. Pre-existing, not shown: the author's record system, appeal engine, coverage index, and the published LITMUS standard.";
707|
708|// The phone dock (Nov 1): under 900 px the header's transport gives way to a
709|// fixed bar at the bottom of the screen with 44 px controls, and one line
710|// over them says where the replay is: the state once there is one (the
711|// verdict, or the repair turn), and the count that matters at this moment,
712|// sentences verified once any sentence is on screen, entries read before that
713|// (the total is known from the record ahead of time; the count waits for the
714|// first sentence).
715|export function dockStatus(state: ReplayState): { state: string; count: string } {
716|  const v = state.verdict;
717|  const name = v ? (v.verdict === 'pass' ? 'PASS' : v.verdict === 'blocked' ? 'BLOCKED' : v.verdict === 'declined' ? 'DECLINED' : 'FAILED') : state.repair ? `REPAIR TURN ${state.repair.turn}` : '';
718|  const count = state.sentences.length > 0
719|    ? `${state.counters.sentencesVerified} of ${state.counters.sentencesTotal} verified`
720|    : `${state.counters.entriesRead} of ${state.counters.chartSize} read`;
721|  return { state: name, count };
722|}

