45|  const repaired = run.repair && r.repairs && r.repairs.length > 0 ? ` after ${r.repairs.length} repair turn${r.repairs.length > 1 ? 's' : ''} (post hoc; the first verdict was blocked)` : '';
46|  const provenance = `Drafted by ${run.model} (${run.provider}), run started ${run.startedAt.slice(0, 10)}, from the synthetic record of ${c.patient.alias}${repaired}. Every sentence verified against its cited entry by the LITMUS gate ${version}${hash ? `; input hash ${hash}` : ''}. Synthetic data only.`;
47|  return {
48|    heading: 'Response to claim denial',
49|    to: `${c.payer.name}, ${c.payer.planType}`,
50|    re: `${service}; date of service ${dates}; denied under CARC ${c.denial.carc}${c.denial.rarc ? `, RARC ${c.denial.rarc}` : ''}; ${c.patient.alias}, ${c.patient.age} year old ${c.patient.sex}`,
51|    payerReason: payerRemark(c),
52|    opening: WRIT_OPENING,
53|    sentences,
54|    footnotes,
55|    provenance,
56|    signature: WRIT_SIGNATURE,
57|    band: WRIT_BAND,
58|  };
59|}
60|
61|export function writText(doc: WritDocument): string {
62|  const lines: string[] = [];
63|  lines.push(doc.band, '');
64|  lines.push(doc.heading.toUpperCase(), '');
65|  lines.push(`To: ${doc.to}`);
66|  lines.push(`Re: ${doc.re}`, '');
67|  if (doc.payerReason) lines.push(`The payer’s reason: “${doc.payerReason}”`, '');
68|  lines.push(doc.opening, '');
69|  lines.push(doc.sentences.map(s => `${s.text} [${s.n}]`).join(' '), '');
70|  lines.push('Record cited');
71|  for (const f of doc.footnotes) lines.push(`[${f.n}] ${f.entryId}, ${f.date}, ${f.kind}: “${f.quote}”`);
72|  lines.push('', doc.provenance, '', doc.signature, '');
73|  return lines.join('\n');
74|}
75|
76|// The footnote sheet (Nov 1): on a phone the instrument is the interface and
77|// the evidence comes to the sentence. A tap on a footnote number opens the
78|// cited entry with the verified quote marked inside its text, the criteria
79|// that entry evidences in the gate record, and the gate's stamp on the
80|// sentence. Pure data over the case and the stored result; the page draws it.
81|export interface FootnoteSheet {
82|  n: number;
83|  total: number;
84|  entry: { id: string; date: string; kind: string; text: string } | null;
85|  sentence: string;
86|  quote: string;
87|  // the entry's text split around the quote; match is empty when the quote is not found as written
88|  before: string;
89|  match: string;
90|  after: string;
91|  criteria: { id: string; text: string }[];
92|  status: RecordStatus;
93|  reason: string;
94|}
95|
96|export function footnoteSheet(c: ViewerCase, r: ViewerResult, n: number): FootnoteSheet | null {
97|  const gate = r.gate;
98|  if (!gate) return null;
99|  const s = gate.sentences[n - 1];
100|  if (!s || n < 1) return null;
101|  const e = c.chart.find(x => x.id === s.citation) ?? null;
102|  let before = '', match = '', after = e?.text ?? '';
103|  if (e && s.quote) {
104|    let i = e.text.indexOf(s.quote);
105|    if (i < 0) i = e.text.toLowerCase().indexOf(s.quote.toLowerCase());
106|    if (i >= 0) { before = e.text.slice(0, i); match = e.text.slice(i, i + s.quote.length); after = e.text.slice(i + s.quote.length); }
107|  }
108|  const ids = new Set(gate.evidence.filter(ev => ev.citation === s.citation).map(ev => ev.criterion));
109|  const criteria = c.criteria.filter(k => ids.has(k.id)).map(k => ({ id: k.id, text: k.text }));
110|  return {
111|    n, total: gate.sentences.length,
112|    entry: e ? { id: e.id, date: e.date, kind: e.kind, text: e.text } : null,
113|    sentence: s.text, quote: s.quote, before, match, after, criteria, status: s.status, reason: s.reason,
114|  };
115|}

