Read text file `build/scripts/check-viewer.ts`.
1|// Verifies the built viewer in headless Chromium, the way a judge's browser
2|// would see it, instead of by reading the source: serves viewer/ on a local
3|// port, opens the page with playwright-core on the Chromium that Playwright
4|// installs, and fails on any console error or page error. Checks: the compare
5|// tab lays out three columns for every case; a repaired case shows the repair
6|// banner at the repair step and a re-stamped sentence at the verdict; the
7|// model's why types out under the chart header on a read; the narrow-screen
8|// rules (the phone shell) leave the desktop page pixel for pixel unchanged,
9|// and on a phone-sized viewport the dock drives the replay. Writes frames to
10|// --out (default the system temp directory) so a reader can look at them.
11|// `npm run viewer:check` after `npm run viewer`.
12|import { spawn } from 'node:child_process';
13|import { readFileSync, readdirSync, mkdirSync, writeFileSync } from 'node:fs';
14|import { join, dirname } from 'node:path';
15|import { tmpdir } from 'node:os';
16|import { fileURLToPath } from 'node:url';
17|import { parseArgs } from 'node:util';
18|import { chromium } from 'playwright-core';
19|import { buildTimeline, type ResultsFile, type ViewerCase } from '../viewer/src/replay.js';
20|
21|const here = dirname(fileURLToPath(import.meta.url));
22|const viewer = join(here, '..', 'viewer');
23|const { values } = parseArgs({ options: { out: { type: 'string' }, port: { type: 'string', default: '8791' } } });
24|const out = values.out ?? join(tmpdir(), 'ypid-viewer-check');
25|mkdirSync(out, { recursive: true });
26|const port = Number(values.port);
27|
28|async function waitForServer(url: string): Promise<void> {
29|  for (let i = 0; i < 50; i++) {
30|    try { const r = await fetch(url); if (r.ok) return; } catch { /* not yet */ }
31|    await new Promise(r => setTimeout(r, 100));
32|  }
33|  throw new Error(`server did not answer at ${url}`);
34|}
35|
36|// Removes every `@media (max-width: 900px) { ... }` block, braces matched, so
37|// the stylesheet can be rendered as the desktop alone sees it.
38|export function stripNarrow(css: string): string {
39|  const open = '@media (max-width: 900px)';
40|  let out = css;
41|  for (let at = out.indexOf(open); at !== -1; at = out.indexOf(open)) {
42|    const brace = out.indexOf('{', at);
43|    let depth = 0, i = brace;
44|    for (; i < out.length; i++) {
45|      if (out[i] === '{') depth++;
46|      else if (out[i] === '}' && --depth === 0) break;
47|    }
48|    out = out.slice(0, at) + out.slice(i + 1);
49|  }
50|  return out;
51|}
52|
53|async function main(): Promise<void> {
54|  const server = spawn('python3', ['-m', 'http.server', String(port), '--directory', viewer], { stdio: 'ignore' });
55|  const base = `http://127.0.0.1:${port}/`;
56|  const problems: string[] = [];
57|  try {
58|    await waitForServer(`${base}data/index.json`);
59|    const manifest = JSON.parse(readFileSync(join(viewer, 'data', 'index.json'), 'utf8')) as { results: { file: string; group?: string; model: string; repair?: number; live?: boolean }[] };
60|    const cases = JSON.parse(readFileSync(join(viewer, 'data', 'cases.json'), 'utf8')) as ViewerCase[];
61|    const browser = await chromium.launch({ headless: true });
62|    const page = await browser.newPage({ viewport: { width: 1600, height: 1000 }, reducedMotion: 'no-preference' });
63|    page.on('console', m => { if (m.type() === 'error') problems.push(`console error: ${m.text()}`); });
64|    page.on('pageerror', e => problems.push(`page error: ${e.message}`));
65|    const go = async (hash: string): Promise<void> => {
66|      await page.goto(`${base}#${hash}`, { waitUntil: 'load' });
67|      await page.waitForFunction(() => document.querySelectorAll('#entries .entry').length > 0 || !document.getElementById('stage')!.hidden === false, null, { timeout: 10_000 });
68|    };
69|
70|    // 1. The compare tab, every case: three columns, no errors.
71|    const kept = manifest.results.filter(m => (m.group ?? 'kept') === 'kept' && m.live);
72|    const keptFile = kept.find(m => m.model === 'muse-spark-1.3')?.file ?? kept[0]!.file;
73|    let compared = 0;
74|    for (const c of cases) {
75|      await go(`file=${encodeURIComponent(keptFile)}&case=${c.id}&view=compare`);
76|      await page.waitForFunction(() => document.querySelectorAll('#compare .col').length === 3, null, { timeout: 10_000 }).catch(() => problems.push(`compare: ${c.id} did not lay out three columns`));
77|      const head = await page.textContent('#compare-case');
78|      if (!head?.includes(c.id)) problems.push(`compare: ${c.id} header reads ${head}`);
79|      compared++;
80|    }
81|    await go(`file=${encodeURIComponent(keptFile)}&case=case-001&view=compare`);
82|    await page.waitForFunction(() => document.querySelectorAll('#compare .col').length === 3, null, { timeout: 10_000 });
83|    await page.screenshot({ path: join(out, 'compare-case-001.png'), fullPage: true });
84|
85|    // 2. A repaired case: the banner at the repair step, the re-stamp at the verdict.
86|    const repairRuns = manifest.results.filter(m => m.group === 'repair');
87|    let repairedShown = 0;
88|    for (const m of repairRuns) {
89|      const file = JSON.parse(readFileSync(join(viewer, 'data', 'results', m.file), 'utf8')) as ResultsFile;
90|      const repaired = file.results.filter(r => r.firstGate && (r.repairs?.length ?? 0) > 0);
91|      for (const r of repaired) {
92|        const c = cases.find(x => x.id === r.caseId)!;
93|        const steps = buildTimeline(r, c);
94|        const repairAt = steps.findIndex(s => s.kind === 'repair');
95|        await go(`file=${encodeURIComponent(m.file)}&case=${r.caseId}&step=${repairAt + 1}`);
96|        await page.waitForSelector('#verdict[data-verdict="repair"]', { timeout: 10_000 }).catch(() => problems.push(`repair: ${m.file} ${r.caseId} shows no repair banner at step ${repairAt + 1}`));
97|        if (repairedShown === 0) await page.screenshot({ path: join(out, `repair-${r.caseId}-banner.png`), fullPage: true });
98|        await go(`file=${encodeURIComponent(m.file)}&case=${r.caseId}&step=end`);
99|        await page.waitForSelector('#verdict .after-repair', { timeout: 10_000 }).catch(() => problems.push(`repair: ${m.file} ${r.caseId} verdict does not say after repair`));
100|        const restamped = await page.locator('.sentence.restamped').count();
101|        const expectRestamp = steps.some(s => s.kind === 'sentence' && s.previous);
102|        if (expectRestamp && restamped === 0) problems.push(`repair: ${m.file} ${r.caseId} has no re-stamped sentence at the verdict`);
103|        if (repairedShown === 0) await page.screenshot({ path: join(out, `repair-${r.caseId}-verdict.png`), fullPage: true });
104|        repairedShown++;
105|      }
106|    }
107|
108|    // 3. The why: on a read step of a run that carries it, the line is visible and typed.
109|    const whyRun = repairRuns.find(m => m.model === 'muse-spark-1.3') ?? repairRuns[0];
110|    if (whyRun) {
111|      const file = JSON.parse(readFileSync(join(viewer, 'data', 'results', whyRun.file), 'utf8')) as ResultsFile;
112|      const r = file.results.find(x => x.caseId === 'case-001')!;
113|      const steps = buildTimeline(r, cases.find(x => x.id === 'case-001')!);
114|      const readAt = steps.findIndex(s => s.kind === 'read' && s.why);
115|      await go(`file=${encodeURIComponent(whyRun.file)}&case=case-001&step=${readAt + 1}`);
116|      await page.waitForSelector('#chart-why:not([hidden])', { timeout: 10_000 }).catch(() => problems.push('why: the chart-why line did not show on a read step'));
117|      const step = steps[readAt];
118|      const expected = step && step.kind === 'read' ? step.why ?? '' : '';
119|      await page.waitForFunction((txt: string) => (document.getElementById('chart-why')?.textContent ?? '').includes(txt), expected, { timeout: 15_000 }).catch(() => problems.push(`why: the typed text never reached "${expected.slice(0, 40)}"`));
120|      await page.screenshot({ path: join(out, 'why-case-001.png'), fullPage: false });
121|    }
122|
123|    // 4. The scoreboard and the default landing still work.
124|    await page.goto(base, { waitUntil: 'load' });
125|    await page.keyboard.press('Escape');
126|    await page.waitForFunction(() => document.querySelectorAll('#entries .entry').length > 0, null, { timeout: 10_000 });
127|    await page.keyboard.press('s');
128|    await page.waitForFunction(() => document.querySelectorAll('#board-table tr').length >= 10, null, { timeout: 10_000 }).catch(() => problems.push('scoreboard: fewer than nine rows'));
129|    const boardRows = await page.locator('#board-table tr').count();
130|
131|    // 5. The presenter spotlight: a region is ringed on request and cleared on null; the page never sets it itself.
132|    await page.keyboard.press('s');
133|    const spotIdle = await page.evaluate(() => document.body.hasAttribute('data-spot') || document.querySelector('.spot') !== null);
134|    if (spotIdle) problems.push('spotlight: set without being asked');
135|    const spotOn = await page.evaluate(() => (window as unknown as { ypid: { spotlight: (n: string | null) => boolean } }).ypid.spotlight('chart') && document.querySelector('.panel.chart.spot') !== null && document.body.getAttribute('data-spot') === 'chart');
136|    if (!spotOn) problems.push('spotlight: chart did not ring');
137|    await page.keyboard.press('End');
138|    await page.waitForFunction(() => document.querySelectorAll('li.sentence').length > 0, null, { timeout: 10_000 }).catch(() => problems.push('spotlight: no sentences at the verdict'));
139|    const spotSentence = await page.evaluate(() => (window as unknown as { ypid: { spotlight: (n: string | null) => boolean } }).ypid.spotlight('sentence:0'));
140|    if (spotSentence !== true) problems.push('spotlight: sentence 0 did not ring');
141|    await page.screenshot({ path: join(out, 'spotlight-sentence.png'), fullPage: false });
142|    const spotOff = await page.evaluate(() => !(window as unknown as { ypid: { spotlight: (n: string | null) => boolean } }).ypid.spotlight(null) && document.querySelector('.spot') === null && !document.body.hasAttribute('data-spot'));
143|    if (!spotOff) problems.push('spotlight: null did not clear');
