147|    //    touching nothing they show.
148|    const still = await browser.newPage({ viewport: { width: 1600, height: 1000 }, reducedMotion: 'reduce' });
149|    still.on('console', m => { if (m.type() === 'error') problems.push(`console error: ${m.text()}`); });
150|    still.on('pageerror', e => problems.push(`page error: ${e.message}`));
151|    await still.goto(`${base}#file=${encodeURIComponent(keptFile)}&case=case-025&step=end`, { waitUntil: 'load' });
152|    await still.waitForFunction(() => document.querySelectorAll('li.sentence').length > 0 && document.fonts.status === 'loaded', null, { timeout: 15_000 }).catch(() => problems.push('invariance: the verdict frame did not render'));
